<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import loyaltyApi from '@/api/loyalty.api'
import { getApiErrorMessage } from '@/api/error'
const router=useRouter(), data=ref({results:[]}), loading=ref(false), error=ref(''), search=ref(''), page=ref(1), source=ref(''), activity=ref('')
let timer
async function load(){loading.value=true;error.value='';try{data.value=await loyaltyApi.customers({search:search.value,page:page.value,source:source.value,activity:activity.value})}catch(e){error.value=getApiErrorMessage(e)}finally{loading.value=false}}
watch(search,()=>{clearTimeout(timer);page.value=1;timer=setTimeout(load,350)}); watch([source,activity],()=>{page.value=1;load()}); onMounted(load)
const fa=v=>Number(v||0).toLocaleString('fa-IR')
</script>
<template><div class="loyalty-page"><header class="loyalty-header"><div><h1>اعضای باشگاه</h1><p>پروفایل یکپارچه مشتریان آنلاین، حضوری و تلفنی</p></div><RouterLink class="admin-button admin-button--primary" to="/dashboard/loyalty/customers/new">ثبت مشتری جدید</RouterLink></header><section class="loyalty-card loyalty-filters"><input v-model="search" placeholder="نام، موبایل، کد عضویت یا ۴ رقم آخر"><select v-model="source"><option value="">همه منابع ثبت‌نام</option><option value="online">آنلاین</option><option value="in_store">حضوری</option><option value="phone">تلفنی</option><option value="admin">ادمین</option></select><select v-model="activity"><option value="">همه مشتریان</option><option value="new">جدید</option><option value="repeat">تکرار خرید</option><option value="inactive">غیرفعال</option></select></section><p v-if="error" class="loyalty-error">{{error}}</p><section class="loyalty-card loyalty-table-wrap"><p v-if="loading" class="loyalty-empty">در حال بارگذاری…</p><table v-else class="loyalty-table"><thead><tr><th>مشتری</th><th>موبایل</th><th>کد عضویت</th><th>سطح</th><th>امتیاز</th><th>کیف پول</th><th>سفارش</th><th>خرید تأییدشده</th><th>منبع</th><th>وضعیت</th></tr></thead><tbody><tr v-for="m in data.results" :key="m.id" tabindex="0" @click="router.push(`/dashboard/loyalty/customers/${m.customer_id}`)" @keydown.enter="router.push(`/dashboard/loyalty/customers/${m.customer_id}`)"><td>{{m.name||'بدون نام'}}</td><td>{{m.masked_phone}}</td><td>{{m.membership_code}}</td><td><span class="loyalty-badge">{{m.tier_name||'عادی'}}</span></td><td>{{fa(m.points)}}</td><td>{{fa(m.wallet_balance)}}</td><td>{{fa(m.completed_orders)}}</td><td>{{fa(m.verified_spend)}}</td><td>{{{online:'آنلاین',in_store:'حضوری',phone:'تلفنی',admin:'ادمین'}[m.registration_source]}}</td><td>{{m.status==='active'?'فعال':'غیرفعال'}}</td></tr><tr v-if="!data.results.length"><td colspan="10" class="loyalty-empty">هنوز عضوی ثبت نشده است.</td></tr></tbody></table></section><nav v-if="data.total_pages>1" class="loyalty-pagination"><button class="admin-button admin-button--secondary" :disabled="page<=1" @click="page--;load()">قبلی</button><span>{{page.toLocaleString('fa-IR')}} از {{data.total_pages.toLocaleString('fa-IR')}}</span><button class="admin-button admin-button--secondary" :disabled="page>=data.total_pages" @click="page++;load()">بعدی</button></nav></div></template>
